const customer = $input.item.json;

// --- Calcul des scores par dimension ---

// 1. Score connexions (30 pts)
let loginScore = 0;
if (customer.logins_last_14_days >= 15) loginScore = 30;
else if (customer.logins_last_14_days >= 7) loginScore = 20;
else if (customer.logins_last_14_days >= 3) loginScore = 10;
else loginScore = 0;

// 2. Score features (25 pts)
const featuresUsed = customer.key_features_used.length;
let featureScore = 0;
if (featuresUsed >= 4) featureScore = 25;
else if (featuresUsed >= 2) featureScore = 15;
else if (featuresUsed >= 1) featureScore = 8;
else featureScore = 0;

// 3. Score support (20 pts)
let supportScore = 20;
if (customer.open_tickets >= 3) supportScore = 0;
else if (customer.open_tickets >= 1) supportScore = 10;
if (customer.last_ticket_sentiment === "very_negative") supportScore -= 5;
if (customer.last_ticket_sentiment === "positive") supportScore += 0;
supportScore = Math.max(0, supportScore);

// 4. Score paiement (15 pts)
let paymentScore = 0;
if (customer.last_payment_status === "paid") paymentScore = 15;
else if (customer.last_payment_status === "pending") paymentScore = 8;
else paymentScore = 0;

// 5. Score renouvellement (10 pts)
let renewalScore = 0;
if (customer.days_until_renewal > 14) renewalScore = 10;
else if (customer.days_until_renewal > 5) renewalScore = 6;
else renewalScore = 2;

// --- Score total ---
const totalScore = loginScore + featureScore + supportScore + paymentScore + renewalScore;

// --- Niveau de risque ---
let riskLevel = "";
let riskEmoji = "";
if (totalScore >= 70) { riskLevel = "FAIBLE"; riskEmoji = "🟢"; }
else if (totalScore >= 40) { riskLevel = "MOYEN"; riskEmoji = "🟡"; }
else if (totalScore >= 20) { riskLevel = "CRITIQUE"; riskEmoji = "🔴"; }
else { riskLevel = "TRES_CRITIQUE"; riskEmoji = "⚫"; }

return {
  json: {
    ...customer,
    scores: {
      login: loginScore,
      feature: featureScore,
      support: supportScore,
      payment: paymentScore,
      renewal: renewalScore,
      total: totalScore
    },
    risk_level: riskLevel,
    risk_emoji: riskEmoji,
    scored_at: new Date().toISOString()
  }
};

const c = $input.item.json;

const promptText = `Tu es un expert en Customer Success pour une entreprise SaaS.
Analyse ce profil client et génère un diagnostic structuré.

CLIENT : ${c.name}
Plan : ${c.plan} | MRR : $${c.mrr}/mois
Score de santé : ${c.score_total}/100
Niveau de risque : ${c.risk_level}

SIGNAUX DÉTECTÉS :
- Connexions (14 derniers jours) : ${c.logins_last_14_days}
- Features utilisées : ${c.key_features_used || "aucune"}
- Tickets support ouverts : ${c.open_tickets}
- Sentiment dernier ticket : ${c.last_ticket_sentiment}
- Statut paiement : ${c.last_payment_status}
- Jours avant renouvellement : ${c.days_until_renewal}
- Utilisateurs actifs : ${c.active_users}

Réponds UNIQUEMENT avec le JSON brut.
Pas de texte avant, pas de backticks, pas d'explication.
Commence directement par { et termine par }

{
  "diagnostic": "2-3 phrases",
  "raison_principale": "cause principale",
  "action_recommandee": "action concrète",
  "message_client": "email court prêt à envoyer"
}`;

const geminiBody = JSON.stringify({
  contents: [
    {
      parts: [
        { text: promptText }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 2048,
    responseMimeType: "application/json"
  }
});

return {
  json: {
    ...c,
    gemini_body: geminiBody
  }
};

const geminiResponse = $input.item.json;

// Récupère les données client depuis le nœud Build Prompt
const customerData = $('Build Prompt1').item.json;

const rawResponse = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';

let aiAnalysis;
try {
  const clean = rawResponse.replace(/```json|```/g, '').trim();
  aiAnalysis = JSON.parse(clean);
} catch(e) {
  aiAnalysis = {
    diagnostic: rawResponse,
    raison_principale: "Erreur de parsing",
    action_recommandee: "Vérifier manuellement",
    message_client: ""
  };
}

return {
  json: {
    id: customerData.id,
    name: customerData.name,
    email: customerData.email,
    score_total: customerData.score_total,
    risk_level: customerData.risk_level,
    ai_diagnostic: aiAnalysis.diagnostic,
    ai_raison: aiAnalysis.raison_principale,
    ai_action: aiAnalysis.action_recommandee,
    ai_message_client: aiAnalysis.message_client
  }
};
